import Foundation
import TraklyCore
import UIKit

/// The native copy (docs/specs/phase10-apps-and-stores.md D17, §J4): every Persian string of the app comes from
/// `fa.lproj/Localizable.strings`, generated by `node shared/app/build.mjs` from `shared/app/copy.fa.json` with the
/// writing rule applied, a leading Latin run and every placeholder isolated. Nothing here holds a Persian literal.
enum L {
    /// The text of `key`.
    static func s(_ key: String) -> String {
        NSLocalizedString(key, tableName: "Localizable", bundle: .main, value: key, comment: "")
    }

    /// The text of `key` with its placeholders filled in order (Persian digits are the caller's: `Fa.number`).
    static func f(_ key: String, _ values: String...) -> String {
        Fa.format(s(key), values)
    }

    /// The labels of a list joined with the copy's separator, each one isolated.
    static func list(_ labels: [String]) -> String {
        Fa.list(labels, separator: s("list_separator"))
    }

    /// Whether the copy has `key` (a key added to copy.fa.json later than this build's generated strings).
    static func has(_ key: String) -> Bool {
        NSLocalizedString(key, tableName: "Localizable", bundle: .main, value: "\u{0}", comment: "") != "\u{0}"
    }

    /// The affirmative button of a JS confirm or alert: the copy's `dialog_ok` once it ships to iOS, else the
    /// system's own word (the device language, like the system sheets, §A3).
    static var ok: String {
        if has("dialog_ok") { return s("dialog_ok") }
        return Bundle(for: UIApplication.self).localizedString(forKey: "OK", value: "OK", table: nil)
    }
}
